(() => {
 const out={bodyClass:document.body.className, backdrops:document.querySelectorAll('.modal-backdrop').length};
 out.modals=[...document.querySelectorAll('.modal')].map(d=>{
   let top=null; let el=d;
   const st=[]; 
   // find effective visibility by walking ancestors
   let hidden=false, e=d;
   while(e){ const cs=getComputedStyle(e); if(cs.display==='none'||cs.visibility==='hidden'||cs.opacity==='0'){hidden=true;break;} e=e.parentElement; }
   return {cls:d.className, title:(d.querySelector('.modal-title')||{}).innerText, hiddenByAncestor:hidden, hasShow:d.classList.contains('show'), z:getComputedStyle(d).zIndex};
 });
 return out;
})()

(() => {
 const resolve = (txt) => {
   const all=[...document.querySelectorAll('.modal')];
   for(const d of all){
     const btns=[...d.querySelectorAll('button')];
     const b=btns.find(x=>x.innerText.trim()===txt);
     if(b){ const r=b.getBoundingClientRect(); const cx=r.left+r.width/2, cy=r.top+r.height/2;
       const top=document.elementFromPoint(cx,cy);
       return {modalTitle:(d.querySelector('.modal-title')||{}).innerText, rect:[r.x|0,r.y|0,r.width|0,r.height|0], topEl: top? (top.tagName+'.'+top.className).slice(0,80):null, topIsSelfOrChild: top? (b===top||b.contains(top)||top.contains(b)):false, disabled:b.disabled, pointerEvents:getComputedStyle(b).pointerEvents};
     }
   }
   return null;
 };
 return {sendCancel: resolve('Send and cancel'), discard: resolve('Discard'), cancel: resolve('Cancel'), close: resolve('Close')};
})()

(() => {
