   let hit=null;
   if(r){const cx=r.left+r.width/2, cy=r.top+r.height/2; const e=document.elementFromPoint(cx,cy); hit=e?(e.tagName+'.'+(e.className||'')).slice(0,60):null; }
   res.push({title:(d.querySelector('.modal-title')||{}).innerText, dlgRect:r?[r.x|0,r.y|0,r.width|0,r.height|0]:null, hitAtCenter:hit, parentOfDialog:d.parentElement.className});
 });
 return {modals:res, backdrops:document.querySelectorAll('.modal-backdrop').length, bodyChildren:[...document.body.children].map(c=>c.tagName+'.'+c.className)};
})()
